package run.ikaros.finance; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/finance/ledgers/{ledgerId}/reconciliations") public class ReconciliationController{private final ReconciliationService service;public ReconciliationController(ReconciliationService s){service=s;}@PostMapping public Mono<ReconciliationView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@Valid@RequestBody CreateReconciliationRequest r){return service.create(a,ledgerId,r);}@GetMapping public Flux<ReconciliationView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId){return service.list(a,ledgerId);}@PostMapping("/{id}/actions/close")public Mono<ReconciliationView> close(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.close(a,id);}}
